// GCD - Euclidean algorithm
function gcd(a, b) {
  return b === 0 ? a : gcd(b, a % b);
}

// LCM - divide first to prevent overflow
function lcm(a, b) {
  return (a / gcd(a, b)) * b;
}

// Fast modular exponentiation - O(log exp)
function modPow(base, exp, mod) {
  let result = 1n;
  base = BigInt(base) % BigInt(mod);
  mod = BigInt(mod);
  exp = BigInt(exp);
  while (exp > 0n) {
    if (exp & 1n) result = result * base % mod;  // odd exponent: multiply in current base
    base = base * base % mod;                    // square the base each step
    exp >>= 1n;
  }
  return Number(result);
}

// Modular inverse via Fermat's little theorem (mod must be prime)
function modInverse(a, p) {
  return modPow(a, p - 2, p);
}

// Safe mod for negative numbers in JS
function safeMod(n, m) {
  return ((n % m) + m) % m;
}
